62	  uint32_t mem_ctrl1_after;
63	  uint32_t mem_ctrl2_before;
64	  uint32_t mem_ctrl2_after;
65	};
66	
67	/* CP owns these shared SYS controls while CPU1 is held in reset.  Keep the
68	 * three whole-word RMW operations in that exclusive window, then verify the
69	 * hardware-visible values before AP can execute any audio initialization.
70	 */
71	
72	static int bk7258_ap_audio_wake(
73	  struct bk7258_ap_audio_wake_s *state)
74	{
75	  state->power_before =
76	    bk7258_ap_reg_read(BK7258_SYS_POWER_WAKEUP);
77	  state->mem_ctrl1_before =
78	    bk7258_ap_reg_read(BK7258_SYS_DEV_MEM_CTRL1);
79	  state->mem_ctrl2_before =
80	    bk7258_ap_reg_read(BK7258_SYS_DEV_MEM_CTRL2);
81	
82	  bk7258_ap_reg_write(BK7258_SYS_POWER_WAKEUP,
83	                      state->power_before &
84	                      ~BK7258_SYS_AUDP_POWER_DOWN);
85	  bk7258_ap_reg_write(BK7258_SYS_DEV_MEM_CTRL1,
86	                      state->mem_ctrl1_before &
87	                      ~BK7258_SYS_AUD_MEM_LOW_POWER);
88	  bk7258_ap_reg_write(BK7258_SYS_DEV_MEM_CTRL2,
89	                      state->mem_ctrl2_before &
90	                      ~BK7258_SYS_AUD_MEM_LOW_POWER);
91	  bk7258_ap_lifecycle_barrier();
92	  up_udelay(10);
93	
94	  state->power_after =
95	    bk7258_ap_reg_read(BK7258_SYS_POWER_WAKEUP);
96	  state->mem_ctrl1_after =
97	    bk7258_ap_reg_read(BK7258_SYS_DEV_MEM_CTRL1);
98	  state->mem_ctrl2_after =
99	    bk7258_ap_reg_read(BK7258_SYS_DEV_MEM_CTRL2);
100	
101	  if ((state->power_after & BK7258_SYS_AUDP_POWER_DOWN) != 0 ||
102	      (state->mem_ctrl1_after & BK7258_SYS_AUD_MEM_LOW_POWER) != 0 ||
103	      (state->mem_ctrl2_after & BK7258_SYS_AUD_MEM_LOW_POWER) != 0)
104	    {
105	      return -EIO;
106	    }
107	
108	  return 0;
109	}
