128	static int bk7258_ap_force_reset(void)
129	{
130	  irqstate_t flags;
131	  uint32_t control;
132	  uint32_t status;
133	  unsigned int count;
134	
135	  flags = up_irq_save();
136	  control = bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL);
137	  control &= ~BK7258_SYS_CPU1_RESET_RELEASE;
138	  bk7258_ap_reg_write(BK7258_SYS_CPU1_CTRL, control);
139	  bk7258_ap_lifecycle_barrier();
140	  if ((bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL) &
141	       BK7258_SYS_CPU1_RESET_RELEASE) != 0)
142	    {
143	      up_irq_restore(flags);
144	      return -EIO;
145	    }
146	
147	  for (count = 0; count < BK7258_AP_POWER_WAIT_LOOPS; count++)
148	    {
149	      status = bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS);
150	      if ((status & BK7258_SYS_CPU1_RESET_STATE) == 0)
151	        {
152	          up_irq_restore(flags);
153	          return 0;
154	        }
155	    }
156	
157	  up_irq_restore(flags);
158	  return -ETIMEDOUT;
159	}
