1	/****************************************************************************
2	 * apps/testing/bk7258_pcm/bk7258_pcm_main.c
3	 *
4	 * Minimal driver-validation utility for the BK7258 internal-DAC audio
5	 * lower-half (/dev/audio/pcm0p).  Generates a fixed-frequency sine wave in
6	 * memory, feeds it into the audio device via AUDIOIOC_ENQUEUEBUFFER and
7	 * waits for AUDIO_MSG_COMPLETE.  Not a functional player.
8	 *
9	 * Usage:
10	 *   bk7258_pcm [-r rate] [-c channels] [-f freq_hz] [-d duration_ms]
11	 *              [-v volume]
12	 *
13	 * Defaults: 48 kHz, stereo, 1 kHz sine, 2000 ms, volume 80.
14	 ****************************************************************************/
15	
16	#include <nuttx/config.h>
17	
18	#include <sys/ioctl.h>
19	#include <sys/types.h>
20	
21	#include <errno.h>
22	#include <fcntl.h>
23	#include <math.h>
24	#include <mqueue.h>
25	#include <stdint.h>
26	#include <stdio.h>
27	#include <stdlib.h>
28	#include <string.h>
29	#include <time.h>
30	#include <unistd.h>
31	
32	#include <nuttx/audio/audio.h>
33	
34	#ifdef CONFIG_AUDIO_BK7258
35	#  include <arch/chip/bk7258_gdma.h>
36	#  include <arch/chip/bk7258_dac.h>
37	#endif
38	
39	#define PCM_DEV_PATH  "/dev/audio/pcm0p"
40	#define MQ_NAME       "/bk7258_pcm_mq"
41	
42	static int      g_sample_rate   = 48000;
43	static int      g_channels      = 2;
44	static int      g_freq_hz       = 1000;
45	static int      g_duration_ms   = 2000;
46	static int      g_volume        = 80;
47	static int      g_trace_mode    = 0; /* -T: sample regs instead of mq. */
48	static int      g_fifo_cpu_mode = 0; /* -F: CPU-to-DAC FIFO boundary.  */
49	
50	static void usage(FAR const char *prog)
51	{
52	  fprintf(stderr,
53	          "Usage: %s [-r rate] [-c channels] [-f freq_hz]"
54	          " [-d duration_ms] [-v volume] [-T] [-F]\n", prog);
55	  exit(EXIT_FAILURE);
56	}
57	
58	static void parse_args(int argc, FAR char *argv[])
59	{
60	  int opt;
61	
62	  while ((opt = getopt(argc, argv, "r:c:f:d:v:TFh")) != -1)
63	    {
64	      switch (opt)
65	        {
66	          case 'r': g_sample_rate   = atoi(optarg); break;
67	          case 'c': g_channels      = atoi(optarg); break;
68	          case 'f': g_freq_hz       = atoi(optarg); break;
69	          case 'd': g_duration_ms   = atoi(optarg); break;
70	          case 'v': g_volume        = atoi(optarg); break;
71	          case 'T': g_trace_mode    = 1;            break;
72	          case 'F': g_fifo_cpu_mode = 1;            break;
73	          case 'h':
74	          default:  usage(argv[0]);
75	        }
76	    }
77	}
78	
79	/* Fill an S16_LE buffer with a bounded sine wave at g_freq_hz.  phase is
80	 * carried across buffers so sample-boundary discontinuities do not create
81	 * audible clicks.
82	 */
83	
84	static void fill_sine(FAR int16_t *dst, size_t nsamples,
85	                      FAR double *phase)
86	{
87	  const double step = 2.0 * M_PI * g_freq_hz / (double)g_sample_rate;
88	  const int16_t amp = 20000;   /* headroom below full-scale.            */
89	  size_t i;
90	
91	  for (i = 0; i < nsamples; i += g_channels)
92	    {
93	      int16_t s = (int16_t)(amp * sin(*phase));
94	      int c;
95	
96	      for (c = 0; c < g_channels; c++)
97	        {
98	          dst[i + c] = s;
99	        }
100	
101	      *phase += step;
102	      if (*phase >= 2.0 * M_PI)
103	        {
104	          *phase -= 2.0 * M_PI;
105	        }
106	    }
107	}
