436	      volatile uint32_t *p_fifo_status = (volatile uint32_t *)0x47800038u;
437	      volatile uint32_t *p_dtmf_fport  = (volatile uint32_t *)0x47800040u;
438	      volatile uint32_t *p_adc_fport   = (volatile uint32_t *)0x47800044u;
439	      volatile uint32_t *p_dac_fport   = (volatile uint32_t *)0x47800048u;
440	      volatile uint32_t *p_dmic_fport  = (volatile uint32_t *)0x4780004cu;
441	      struct bk7258_dac_stats_s ps;
442	      /* bit30-31 of DAC_CONFIG0 are RESERVED (hardware forces them to 0), so
443	       * the magic stays within bit0-29 to make readback == magic meaningful.
444	       * An impossible HPF2 coef + gain + notchen pattern that the running
445	       * config would never have. */
