54	bk_err_t bk_aud_dac_init(aud_dac_config_t *dac_config)
55	{
56		bk_err_t ret = BK_OK;
57		BK_RETURN_ON_NULL(dac_config);
58	
59		if (bk_aud_get_module_init_sta(AUD_MODULE_DAC)) {
60			LOGW("aud dac is init already %s\n", __func__);
61			return BK_OK;
62		}
63	
64		bk_aud_set_module_init_sta(AUD_MODULE_DAC, true);
65	
66		/* audio common driver init */
67		if (BK_OK != bk_aud_driver_init()) {
68			LOGE("%s, audio driver init fail, line: %d \n", __func__, __LINE__);
69			ret = BK_ERR_AUD_DRV_NOT_INIT;
70			goto fail;
71		}
72	
73		/* select audio clock */
74		bk_aud_clk_config(dac_config->clk_src);
75	
76		if (dac_config->clk_src == AUD_CLK_APLL)
77		{
78			sys_drv_dmic_clk_div_set(0x1);
79		}
80	
81		/*active dac*/
82		sys_drv_aud_dac_bias_en(1);
83		sys_drv_aud_dac_drv_en(1);
84		sys_drv_aud_dac_dcoc_en(1);
85		sys_drv_aud_dac_idac_en(1);
86	
87		//enable dacl and dacr
88		switch (dac_config->dac_chl) {
89			case AUD_DAC_CHL_L:
90				sys_drv_aud_dacr_en(0);
91				sys_drv_aud_dacl_en(1);
92				break;
93	
94			case AUD_DAC_CHL_R:
95				sys_drv_aud_dacr_en(1);
96				sys_drv_aud_dacl_en(0);
97				break;
98	
99			case AUD_DAC_CHL_LR:
100				sys_drv_aud_dacr_en(1);
101				sys_drv_aud_dacl_en(1);
102				break;
103	
104			default:
105				break;
106		}
107	
108		//set dac work mode
109		if (dac_config->work_mode == AUD_DAC_WORK_MODE_SIGNAL_END) {
110			sys_drv_aud_diffen_en(0);
111		} else if (dac_config->work_mode == AUD_DAC_WORK_MODE_DIFFEN) {
112			sys_drv_aud_diffen_en(1);
113		} else {
114			LOGE("%s, audio dac work mode fail, line: %d \n", __func__, __LINE__);
115			ret = BK_FAIL;
116			goto fail;
117		}
118	
119		aud_hal_set_dac_config0_dac_set_gain(dac_config->dac_gain);
120		aud_hal_set_dac_config0_dac_clk_invert(dac_config->dac_clk_invert);
121	
122		aud_hal_set_dac_config0_dac_hpf1_bypass(1);
123		aud_hal_set_dac_config0_dac_hpf2_bypass(1);
124	
125	#if CONFIG_SOC_BK7256XX
126		aud_hal_set_fifo_config_dacl_rd_threshold(4);
127	#endif
128	
129	
130		if (BK_OK != bk_aud_dac_set_samp_rate(dac_config->samp_rate)) {
131			ret = BK_FAIL;
132			goto fail;
133		}
134	
135		return ret;
136	
137	fail:
138		bk_aud_set_module_init_sta(AUD_MODULE_DAC, false);
139		return ret;
140	}
