142	bk_err_t bk_aud_dac_deinit(void)
143	{
144		AUD_DAC_RETURN_ON_NOT_INIT();
145	
146		bk_aud_dac_stop();
147	
148		/* disable int */
149		bk_aud_dac_dacl_disable_int();
150		bk_aud_dac_dacr_disable_int();
151	
152		//enable dacl and dacr
153		sys_drv_aud_dacr_en(0);
154		sys_drv_aud_dacl_en(0);
155	
156		/*active dac*/
157		sys_drv_aud_dac_bias_en(0);
158		sys_drv_aud_dac_drv_en(0);
159		sys_drv_aud_dac_dcoc_en(0);
160		sys_drv_aud_dac_idac_en(0);
161	
162		sys_drv_aud_diffen_en(1);
163	
164		aud_hal_set_dac_config0_dac_set_gain(0);
165		aud_hal_set_dac_config0_dac_clk_invert(0);
166	
167		aud_hal_set_dac_config0_dac_hpf1_bypass(0);
168		aud_hal_set_dac_config0_dac_hpf2_bypass(0);
169	
170		bk_aud_dac_set_samp_rate(8000);
171	
172		sys_drv_dmic_clk_div_set(0x0);
173	
174		bk_err_t ret = bk_aud_set_module_init_sta(AUD_MODULE_DAC, false);
175	
176		bk_aud_driver_deinit();
177	
178		return ret;
179	}
