365		/*init audio paramters*/
366		sys_drv_aud_int_en(1);
367	#if CONFIG_SOC_BK7236XX
368	/*
369		sys_hal_set_ana_reg18_value(0x00BF8085);
370		sys_hal_set_ana_reg19_value(0x81800006);
371		sys_hal_set_ana_reg20_value(0xFBC02423);
372		sys_hal_set_ana_reg21_value(0x00500000);
373	*/
374		//sys_hal_aud_aud_en(1);
