154		sys_drv_aud_dacl_en(0);
155	
156		/*active dac*/
157		sys_drv_aud_dac_bias_en(0);
158		sys_drv_aud_dac_drv_en(0);
159		sys_drv_aud_dac_dcoc_en(0);
160		sys_drv_aud_dac_idac_en(0);
