181	bk_err_t bk_aud_dac_set_samp_rate(uint32_t samp_rate)
182	{
183		AUD_DAC_RETURN_ON_NOT_INIT();
184	
185	#if CONFIG_SOC_BK7236XX
186		/* get audio clock config */
187		if (1 == aud_hal_get_audio_config_apll_sel()) {
188			/* config apll */
189			sys_drv_apll_en(1);
190			//set apll clock config
191			if (samp_rate == 11025 || samp_rate == 22050 || samp_rate == 44100) {
192				sys_drv_apll_cal_val_set(0x88AF2EC9);
193			} else {
194				sys_drv_apll_cal_val_set(0x8973CA6F);
195			}
196			sys_drv_apll_config_set(0xC2A0AE86);
197			sys_drv_apll_spi_trigger_set(1);
198			delay(10);
199			sys_drv_apll_spi_trigger_set(0);
200		}
201	#endif
202	
203		/* disable dac handset bit again, to make sure this bit unset */
204		aud_hal_set_extend_cfg_dac_fracmod_manual(0x0);
205	
206		if (samp_rate == 8000) {
207			aud_hal_set_audio_config_samp_rate_dac(0x0);
208		} else if (samp_rate == 11025) {
209			aud_hal_set_extend_cfg_dac_fracmod_manual(0x1);
210			aud_hal_set_dac_fracmod_value(CONST_DIV_44_1K << 2);
211			aud_hal_set_audio_config_samp_rate_dac(0x2);
212		} else if (samp_rate == 12000) {
213			aud_hal_set_extend_cfg_dac_fracmod_manual(0x1);
214			aud_hal_set_dac_fracmod_value(CONST_DIV_48K << 2);
215			aud_hal_set_audio_config_samp_rate_dac(0x3);
216		} else if (samp_rate == 16000) {
217			aud_hal_set_audio_config_samp_rate_dac(0x1);
218		} else if (samp_rate == 22050) {
219			aud_hal_set_extend_cfg_dac_fracmod_manual(0x1);
220			aud_hal_set_dac_fracmod_value(CONST_DIV_44_1K << 1);
221			aud_hal_set_audio_config_samp_rate_dac(0x2);
222		} else if (samp_rate == 24000) {
223			aud_hal_set_extend_cfg_dac_fracmod_manual(0x1);
224			aud_hal_set_dac_fracmod_value(CONST_DIV_48K << 1);
225			aud_hal_set_audio_config_samp_rate_dac(0x3);
226		} else if (samp_rate == 32000) {
227			aud_hal_set_extend_cfg_dac_fracmod_manual(0x1);
228			aud_hal_set_dac_fracmod_value(CONST_DIV_16K >> 1);
