750	bool bk7258_dac_fifo_needs_data(void)
751	{
752	  const uint32_t st = getreg32(BK7258_AUD_FIFO_STATUS);
753	
754	  /* Return true when either channel drops below the read-threshold; the
755	   * caller should replenish enough data to bring both above threshold.
756	   */
757	
758	  return (st & (AUD_FIFO_ST_DACL_NEAR_EMPTY
759	                | AUD_FIFO_ST_DACR_NEAR_EMPTY)) != 0u;
760	}
