42	static int      g_sample_rate   = 48000;
43	static int      g_channels      = 2;
44	static int      g_freq_hz       = 1000;
45	static int      g_duration_ms   = 2000;
46	static int      g_volume        = 80;
47	static int      g_trace_mode    = 0; /* -T: sample regs instead of mq. */
48	static int      g_fifo_cpu_mode = 0; /* -F: CPU-to-DAC FIFO boundary.  */
49	
50	static void usage(FAR const char *prog)
51	{
52	  fprintf(stderr,
53	          "Usage: %s [-r rate] [-c channels] [-f freq_hz]"
54	          " [-d duration_ms] [-v volume] [-T] [-F]\n", prog);
55	  exit(EXIT_FAILURE);
56	}
57	
58	static void parse_args(int argc, FAR char *argv[])
59	{
60	  int opt;
61	
62	  while ((opt = getopt(argc, argv, "r:c:f:d:v:TFh")) != -1)
63	    {
64	      switch (opt)
65	        {
66	          case 'r': g_sample_rate   = atoi(optarg); break;
67	          case 'c': g_channels      = atoi(optarg); break;
68	          case 'f': g_freq_hz       = atoi(optarg); break;
69	          case 'd': g_duration_ms   = atoi(optarg); break;
70	          case 'v': g_volume        = atoi(optarg); break;
71	          case 'T': g_trace_mode    = 1;            break;
72	          case 'F': g_fifo_cpu_mode = 1;            break;
73	          case 'h':
74	          default:  usage(argv[0]);
75	        }
76	    }
77	}
