149	static void bk7258_gpio_rearm_opposite_level_locked(unsigned int pin)
150	{
151	  bool high;
152	  uint32_t regval;
153	
154	  regval  = getreg32(BK7258_GPIO_CFG(pin));
155	  high    = (regval & BK7258_GPIO_CFG_INPUT) != 0;
156	  regval &= ~BK7258_GPIO_INT_ENABLE;
157	  putreg32(regval, BK7258_GPIO_CFG(pin));
158	
159	  /* Arm the level opposite the sampled state.  If the input changes while
160	   * the interrupt is disabled, cleared, or reconfigured, the new level
161	   * remains asserted after re-enable and the hardware raises source 55
162	   * again.  A transition that returns to the sampled level is a net no-op.
163	   */
164	
165	  bk7258_gpio_clear_irq_locked(pin);
166	  bk7258_gpio_set_opposite_level_irq_locked(pin, high);
167	  bk7258_gpio_enable_irq_locked(pin);
168	}
