230	int bk7258_gpio_config_output(unsigned int pin, bool initial)
231	{
232	  irqstate_t flags;
233	  uint32_t regval;
234	
235	  if (!bk7258_gpio_valid(pin))
236	    {
237	      return -EINVAL;
238	    }
239	
240	  flags = enter_critical_section();
241	  bk7258_gpio_select_func_locked(pin);
242	
243	  /* Program the output latch while the output driver is still disabled, then
244	   * switch the pin to output mode.  Keeping both writes in one critical
245	   * section prevents another register update from introducing a glitch.
246	   */
247	
248	  regval = getreg32(BK7258_GPIO_CFG(pin));
249	  if (initial)
250	    {
251	      regval |= BK7258_GPIO_CFG_OUTPUT;
252	    }
253	  else
254	    {
255	      regval &= ~BK7258_GPIO_CFG_OUTPUT;
256	    }
257	
258	  putreg32(regval, BK7258_GPIO_CFG(pin));
259	
260	  regval &= ~(BK7258_GPIO_CFG_MODE_MASK |
261	              BK7258_GPIO_CFG_PULL_MASK |
262	              BK7258_GPIO_CFG_SECOND_FUNC);
263	  regval |= BK7258_GPIO_CFG_MODE_OUTPUT;
264	  putreg32(regval, BK7258_GPIO_CFG(pin));
265	  leave_critical_section(flags);
266	  return OK;
267	}
