#define AUD_ADC_RETURN_ON_NOT_INIT() do {\
		if (!bk_aud_get_module_init_sta(AUD_MODULE_ADC)) {\
			return BK_ERR_AUD_ADC_NOT_INIT;\
		}\
	} while(0)

#define CONST_DIV_16K		(0x06590000)
